#!/usr/bin/env python3
"""
Automated Job Ingestion Script for snehal.fyi
Usage:
  # Method 1: Feed a JSON file generated by your AI tool
  python3 scripts/add_job.py --file new_job.json --push

  # Method 2: Feed a JSON string directly
  python3 scripts/add_job.py --json '{"company": "Apple", "role": "Junior Data Engineer", ...}' --push

  # Method 3: Interactive CLI wizard
  python3 scripts/add_job.py
"""

import json
import os
import re
import sys
import argparse
import subprocess

JOBS_PATH = os.path.join(os.path.dirname(__file__), "..", "src", "data", "jobs.json")

def generate_slug(company: str, role: str) -> str:
    raw = f"{company}-{role}".lower()
    slug = re.sub(r"[^a-z0-9]+", "-", raw).strip("-")
    return slug

def get_next_id(jobs: list) -> str:
    ids = []
    for j in jobs:
        try:
            ids.append(int(j.get("id", 0)))
        except ValueError:
            pass
    return str(max(ids, default=100) + 1)

def add_job(job_data: dict, auto_push: bool = False):
    with open(JOBS_PATH, "r", encoding="utf-8") as f:
        jobs = json.load(f)

    # Auto-generate ID if missing
    if not job_data.get("id"):
        job_data["id"] = get_next_id(jobs)

    # Auto-generate slug if missing
    if not job_data.get("slug"):
        job_data["slug"] = generate_slug(job_data.get("company", ""), job_data.get("role", ""))

    # Ensure required defaults
    job_data.setdefault("category", "Software")
    job_data.setdefault("badge", "Hot")
    job_data.setdefault("logoBg", "bg-neutral-800")
    job_data.setdefault("location", "Pan India / Hybrid")
    job_data.setdefault("jobType", "Full-Time")
    job_data.setdefault("batch", ["2025", "2026", "2027+"])
    job_data.setdefault("salary", "₹6 - ₹10 LPA")
    job_data.setdefault("experience", "Recent Grads & Freshers")
    job_data.setdefault("postedDate", "Today")
    job_data.setdefault("deadline", "Apply ASAP")
    job_data.setdefault("eligibility", ["Recent Grads (2025, 2026, 2027+)", "Relevant Degree", "No active backlogs"])
    job_data.setdefault("description", f"Hiring for {job_data.get('role')} at {job_data.get('company')}.")
    job_data.setdefault("responsibilities", ["Develop and maintain software modules.", "Collaborate with cross-functional engineering teams."])
    job_data.setdefault("requirements", ["Strong fundamentals in programming & problem solving.", "Good communication skills."])
    job_data.setdefault("selectionProcess", ["Online Assessment", "Technical Interview", "HR Discussion"])
    job_data.setdefault("snehalTips", "Tailor your 1-page resume to match keywords from the job description.")
    job_data.setdefault("featured", True)
    job_data.setdefault("tags", [job_data.get("company", ""), "Recent Grads"])

    # Insert at beginning
    jobs.insert(0, job_data)

    with open(JOBS_PATH, "w", encoding="utf-8") as f:
        json.dump(jobs, f, indent=2, ensure_ascii=False)

    print(f"✅ Successfully added Job #{job_data['id']}: {job_data['company']} - {job_data['role']}")
    print(f"👉 Direct URL slug: /jobs/{job_data['slug']}")
    print(f"👉 ManyChat shortlink: /j/{job_data['id']}")

    if auto_push:
        try:
            print("🚀 Committing and pushing to GitHub to trigger Vercel deployment...")
            subprocess.run(["git", "add", "src/data/jobs.json"], check=True)
            msg = f"Auto-post Job #{job_data['id']}: {job_data['company']} - {job_data['role']}"
            subprocess.run(["git", "commit", "-m", msg], check=True)
            subprocess.run(["git", "push"], check=True)
            print("🎉 Done! Pushed to GitHub. Vercel is deploying the update now.")
        except Exception as e:
            print(f"⚠️ Git push failed: {e}")

def main():
    parser = argparse.ArgumentParser(description="Add a new job to snehal.fyi")
    parser.add_argument("--file", help="Path to JSON file containing job details")
    parser.add_argument("--json", help="Raw JSON string containing job details")
    parser.add_argument("--push", action="store_true", help="Automatically git commit and push to trigger Vercel deploy")
    args = parser.parse_args()

    if args.file:
        with open(args.file, "r", encoding="utf-8") as f:
            data = json.load(f)
        add_job(data, auto_push=args.push)
    elif args.json:
        data = json.loads(args.json)
        add_job(data, auto_push=args.push)
    else:
        print("--- Interactive Job Adder ---")
        company = input("Company Name: ").strip()
        role = input("Role Title: ").strip()
        apply_url = input("Official Apply URL: ").strip()
        salary = input("Salary (e.g. ₹12 - ₹15 LPA): ").strip() or "Best in Industry"
        data = {
            "company": company,
            "role": role,
            "applyUrl": apply_url,
            "salary": salary,
        }
        add_job(data, auto_push=args.push)

if __name__ == "__main__":
    main()
